async (page) => {
  const started = new Date().toISOString();
  const browser = page.context().browser();
  const results = [];
  for (const [site, host] of [['resident','ca-resident-demo.happyriver-ace49996.uksouth.azurecontainerapps.io'],['employee','ca-cutover-test-demo-api.happyriver-ace49996.uksouth.azurecontainerapps.io']]) {
    const context = await browser.newContext();
    try {
      const p = await context.newPage();
      const healthAttempts = [];
      const deadline = Date.now()+900000;
      while (Date.now()<deadline) {
        try {
          const response = await context.request.get('https://'+host+'/healthz',{timeout:Math.min(180000,deadline-Date.now())});
          healthAttempts.push({status:response.status()});
          if (response.status()===200) break;
        } catch (error) {
          if (!String(error).toLowerCase().includes('timeout')) throw error;
          healthAttempts.push({timeout:true});
        }
        await p.waitForTimeout(5000);
      }
      if (!healthAttempts.some(a=>a.status===200)) throw new Error(site+' health deadline');
      const consoleTypes=[]; const responseErrors=[]; const pageErrors=[];
      p.on('console',msg=>{if(msg.type()==='error') consoleTypes.push(msg.type());});
      p.on('pageerror',error=>pageErrors.push(error.name));
      p.on('response',response=>{if(response.status()>=400){const u=new URL(response.url());responseErrors.push({origin:u.origin,path:u.pathname,status:response.status()});}});
      const views=[];
      for (const viewport of [{width:1365,height:900},{width:390,height:844}]) {
        await p.setViewportSize(viewport);
        const response=await p.goto('https://'+host+'/',{waitUntil:'networkidle',timeout:180000});
        if(response.status()!==200) throw new Error(site+' public status '+response.status());
        const dom=await p.evaluate(()=>({title:document.title,overflow:document.documentElement.scrollWidth>innerWidth,passwordInputs:document.querySelectorAll('input[type=password]').length,widgetScripts:document.querySelectorAll('script[src="/chat-widget.js"]').length,launchers:document.querySelectorAll('.chat-widget-launcher').length,dialogs:document.querySelectorAll('[role=dialog]').length,signInLinks:[...document.querySelectorAll('a')].filter(a=>/sign in/i.test(a.textContent)).length}));
        if(dom.overflow) throw new Error(site+' horizontal overflow');
        const item={viewport,status:response.status(),dom};
        if(site==='resident') {
          const launcher=p.locator('.chat-widget-launcher');
          if(await launcher.count()!==1 || !await launcher.isVisible()) throw new Error('Resident launcher missing');
          await launcher.click();
          item.widgetOpened=await p.locator('[role=dialog]').isVisible();
          if(!item.widgetOpened) throw new Error('Resident dialog not opened');
          item.noSubmission=true;
        }
        views.push(item);
      }
      const result={site,host,healthAttempts,views,consoleErrorCount:consoleTypes.length,pageErrorNames:pageErrors,responseErrors,noCredentials:true,noModelSubmission:true};
      if(site==='employee') {
        p.removeAllListeners('response'); p.removeAllListeners('console'); p.removeAllListeners('pageerror');
        await p.goto('https://'+host+'/app',{waitUntil:'domcontentloaded',timeout:180000});
        await p.waitForURL(u=>u.hostname==='login.microsoftonline.com',{timeout:180000});
        const final=new URL(p.url());
        result.anonymousAppBoundary={origin:final.origin,path:final.pathname,queryWithheld:true};
      }
      results.push(result);
    } finally { await context.close(); }
  }
  return {started,finished:new Date().toISOString(),results};
}
